import boto3
def handler(event, context):
    ws = boto3.client('workspaces')
    did = event['targetDirectoryId']
    sid = event['sourceDirectoryId']
    if did == sid:
        raise Exception('sourceDirectoryId and targetDirectoryId must differ (%s).' % did)
    dirs = ws.describe_workspace_directories(DirectoryIds=[did]).get('Directories', [])
    if not dirs:
        raise Exception('Target directory %s is not registered with WorkSpaces. Register it first.' % did)
    state = dirs[0].get('State')
    if state not in ('REGISTERED', 'REGISTERING'):
        raise Exception('Target directory %s state is %s; expected REGISTERED.' % (did, state))
    return {'directoryState': state, 'ok': True}

import boto3
def handler(event, context):
    ws = boto3.client('workspaces')
    users = event.get('userList') or []
    # (#19) aws:executeScript output payload is limited (~100 KB); plan/skipped scale with userList.
    # Cap the per-run user list so the step output stays well under the limit (also consistent with the
    # <=25 create cap). Split larger migrations into multiple runs.
    if len(users) > 100:
        raise Exception('userList has %d entries; the maximum supported per run is 100 (SSM executeScript output payload limit). Split into batches of 100 or fewer.' % len(users))
    sid = event['sourceDirectoryId']
    did = event['targetDirectoryId']
    override = (event.get('bundleIdOverride') or '').strip()
    rm = event['runningMode']
    pag = ws.get_paginator('describe_workspaces')
    # Source map: username -> full source WorkSpace record(s), scoped to the source directory.
    src = {}
    for page in pag.paginate(DirectoryId=sid):
        for w in page['Workspaces']:
            u = w.get('UserName')
            src.setdefault(u, {'bundles': set(), 'ws': []})
            src[u]['bundles'].add(w.get('BundleId'))
            src[u]['ws'].append(w)
    tgt = set()
    for page in pag.paginate(DirectoryId=did):
        for w in page['Workspaces']:
            tgt.add(w.get('UserName'))
    plan = []
    createRequests = []
    skipped = []
    for u in users:
        info = src.get(u)
        if u in tgt:
            plan.append({'UserName': u, 'action': 'skip-exists-in-target'})
            skipped.append({'UserName': u, 'reason': 'already has a WorkSpace in target directory'})
            continue
        bundle = None
        reason = None
        srcWs = None
        if info:
            bundles = sorted(b for b in info['bundles'] if b)
            srcWs = info['ws'][0]
            if override:
                bundle = override
            elif len(bundles) == 1:
                bundle = bundles[0]
            elif len(bundles) > 1:
                reason = 'ambiguous: multiple source bundles %s (set bundleIdOverride)' % bundles
            else:
                reason = 'source WorkSpace has no resolvable bundle (set bundleIdOverride)'
        elif override:
            bundle = override
        else:
            reason = 'no source WorkSpace found in %s (set bundleIdOverride to create anyway)' % sid
        if bundle:
            # #4: preserve source WorkSpace properties (encryption, KMS key, volume sizes,
            # compute type, tags). Without this the recreated WorkSpace silently drops volume
            # encryption and resizes to bundle defaults. If there is no source WorkSpace (override
            # path) we fall back to bundle defaults and flag it.
            props = {'RunningMode': rm}
            encHint = 'bundle-default'
            tags = []
            if srcWs:
                sp = srcWs.get('WorkspaceProperties', {})
                # (#18) When an override bundle is set, let the override bundle govern compute/volume sizing.
                # Copying source ComputeTypeName/RootVolumeSizeGib/UserVolumeSizeGib onto a different override
                # bundle can produce an invalid size for that bundle and fail the create.
                if not override:
                    if sp.get('ComputeTypeName'):
                        props['ComputeTypeName'] = sp['ComputeTypeName']
                    if sp.get('RootVolumeSizeGib'):
                        props['RootVolumeSizeGib'] = sp['RootVolumeSizeGib']
                    if sp.get('UserVolumeSizeGib'):
                        props['UserVolumeSizeGib'] = sp['UserVolumeSizeGib']
                req = {'DirectoryId': did, 'UserName': u, 'BundleId': bundle, 'WorkspaceProperties': props}
                vek = srcWs.get('VolumeEncryptionKey')
                if vek:
                    req['VolumeEncryptionKey'] = vek
                    req['RootVolumeEncryptionEnabled'] = bool(srcWs.get('RootVolumeEncryptionEnabled', True))
                    req['UserVolumeEncryptionEnabled'] = bool(srcWs.get('UserVolumeEncryptionEnabled', True))
                    encHint = 'encrypted(%s)' % vek
                # (#17) carry source tags. describe_tags needs workspaces:DescribeTags; do NOT swallow an
                # AccessDenied (that would silently drop tags). Surface a clear permissions error; only a
                # genuinely empty TagList means no tags.
                try:
                    t = ws.describe_tags(ResourceId=srcWs['WorkspaceId']).get('TagList', [])
                    tags = [x for x in t if not x.get('Key','').startswith('aws:')]
                except ws.exceptions.ClientError as e:
                    code = e.response.get('Error', {}).get('Code', '')
                    if code in ('AccessDeniedException', 'AccessDenied', 'UnauthorizedOperation'):
                        raise Exception('describe_tags AccessDenied for %s: automation role is missing workspaces:DescribeTags. Add it to the policy and retry.' % srcWs['WorkspaceId'])
                    raise
                if tags:
                    req['Tags'] = tags
            else:
                req = {'DirectoryId': did, 'UserName': u, 'BundleId': bundle, 'WorkspaceProperties': props}
            createRequests.append(req)
            plan.append({'UserName': u, 'action': 'create', 'bundleId': bundle, 'bundleSource': 'override' if override else 'source', 'encryption': encHint, 'compute': props.get('ComputeTypeName','bundle-default'), 'tagsCarried': len(tags)})
        else:
            plan.append({'UserName': u, 'action': 'skip', 'reason': reason})
            skipped.append({'UserName': u, 'reason': reason})
    # (25-ID cap) DescribeWorkspaces / aws:waitForAwsResourceProperty accept at most 25 WorkspaceIds.
    # This orchestrator waits by WorkspaceIds, so a single run must create at most 25 WorkSpaces.
    if len(createRequests) > 25:
        raise Exception('This run would create %d WorkSpaces; the maximum supported per run is 25 (DescribeWorkspaces WorkspaceIds limit). Split the user list into batches of 25 or fewer.' % len(createRequests))
    # (fae0bb03) Order/empty-directory guard. If the caller asked for users but NOTHING is creatable
    # and nothing was skipped because it already exists in the target, every user failed to resolve
    # (no source WorkSpace and no bundleIdOverride) - the usual symptom of running this document before
    # the AD migration populated the target directory, or against the wrong directory. Fail closed
    # rather than silently produce an empty plan.
    already = [s for s in skipped if 'already has a WorkSpace in target' in (s.get('reason') or '')]
    if users and not createRequests and not already:
        raise Exception('No WorkSpaces can be created for any of the %d requested user(s) and none already exist in the target directory. This usually means the AD migration has not populated the target directory yet, or the documents are being run out of order / against the wrong directory. Resolve the users in the target Managed AD first (or set bundleIdOverride intentionally), then re-run. Skips: %s' % (len(users), skipped))
    return {'plan': plan, 'createRequests': createRequests, 'skipped': skipped, 'toCreateCount': len(createRequests), 'skippedCount': len(skipped), 'userCount': len(users)}

import boto3
def handler(event, context):
    toCreate = int(event.get('toCreateCount') or 0)
    autoReq = (str(event.get('autoRequestQuotaIncrease') or 'false').lower() == 'true')
    QUOTA_CODE = 'L-34278094'  # WorkSpaces (per region); verified via list-service-quotas service-code=workspaces
    region = boto3.session.Session().region_name
    sq = boto3.client('service-quotas')
    ws = boto3.client('workspaces')
    # Resolve the applied limit; fall back to the AWS default if no account-applied override exists.
    limit = None
    try:
        limit = sq.get_service_quota(ServiceCode='workspaces', QuotaCode=QUOTA_CODE)['Quota']['Value']
    except sq.exceptions.NoSuchResourceException:
        limit = sq.get_aws_default_service_quota(ServiceCode='workspaces', QuotaCode=QUOTA_CODE)['Quota']['Value']
    limit = int(limit)
    # Count CURRENT region-wide WorkSpaces (the quota is regional, across all directories).
    current = 0
    for page in ws.get_paginator('describe_workspaces').paginate():
        current += len(page.get('Workspaces', []))
    available = limit - current
    needed = toCreate
    result = {'region': region, 'quotaCode': QUOTA_CODE, 'limit': limit, 'current': current, 'available': available, 'toCreate': needed}
    if needed <= 0:
        result['status'] = 'ok-nothing-to-create'
        return result
    # Look for an already-pending increase request so we don't tell the operator to file a duplicate.
    desired = current + needed
    pending = None
    try:
        hist = sq.list_requested_service_quota_change_history_by_quota(ServiceCode='workspaces', QuotaCode=QUOTA_CODE).get('RequestedQuotas', [])
        for r in hist:
            if r.get('Status') in ('PENDING', 'CASE_OPENED') and float(r.get('DesiredValue', 0)) >= desired:
                pending = {'Id': r.get('Id'), 'CaseId': r.get('CaseId'), 'DesiredValue': r.get('DesiredValue'), 'Status': r.get('Status')}
                break
    except Exception as e:
        result['pendingCheckWarning'] = 'could not read change history: %s' % str(e)
    cmd = ('aws service-quotas request-service-quota-increase --service-code workspaces '
           '--quota-code %s --desired-value %d --region %s') % (QUOTA_CODE, desired, region)
    if needed <= available:
        result['status'] = 'ok'
        if available - needed <= max(1, int(limit * 0.1)):
            result['warning'] = ('This run fits but will leave only %d free WorkSpaces slot(s) of %d (>=90%% utilization after creating %d). Consider requesting an increase: %s' % (available - needed, limit, needed, cmd))
        return result
    # Insufficient quota -> fail closed.
    result['status'] = 'insufficient'
    result['requiredLimit'] = desired
    result['remediationCommand'] = cmd
    if pending:
        result['pendingRequest'] = pending
    filed = None
    if autoReq and not pending:
        try:
            resp = sq.request_service_quota_increase(ServiceCode='workspaces', QuotaCode=QUOTA_CODE, DesiredValue=float(desired))
            rq = resp.get('RequestedQuota', {})
            filed = {'Id': rq.get('Id'), 'CaseId': rq.get('CaseId'), 'DesiredValue': rq.get('DesiredValue'), 'Status': rq.get('Status')}
            result['increaseRequestFiled'] = filed
        except Exception as e:
            result['increaseRequestError'] = str(e)
    # Build the failure message.
    msg = ('WorkSpaces quota preflight FAILED: region %s has %d of %d WorkSpaces used; this run needs %d but only %d slot(s) are free. '
           'Request a WorkSpaces limit increase (quota %s) to at least %d, then re-run. Command: %s') % (region, current, limit, needed, available, QUOTA_CODE, desired, cmd)
    if pending:
        msg += ' NOTE: an increase to %s is already %s (request %s); wait for it to be approved rather than filing another.' % (pending.get('DesiredValue'), pending.get('Status'), pending.get('Id'))
    elif filed:
        msg += ' An increase request to %d was filed on your behalf (request %s, case %s); it is approval-gated and will NOT be effective in this run. Re-run after it is approved.' % (desired, filed.get('Id'), filed.get('CaseId'))
    raise Exception(msg)

import boto3
def handler(event, context):
    ws = boto3.client('workspaces')
    reqs = event.get('createRequests', [])
    created, failed = [], []
    for i in range(0, len(reqs), 25):
        batch = reqs[i:i+25]
        resp = ws.create_workspaces(Workspaces=batch)
        for r in resp.get('PendingRequests', []):
            created.append({'UserName': r.get('UserName'), 'WorkspaceId': r.get('WorkspaceId'), 'State': r.get('State')})
        for fr in resp.get('FailedRequests', []):
            wr = fr.get('WorkspaceRequest', {})
            failed.append({'UserName': wr.get('UserName'), 'ErrorCode': fr.get('ErrorCode'), 'ErrorMessage': fr.get('ErrorMessage')})
    return {'created': created, 'failed': failed, 'createdCount': len(created), 'failedCount': len(failed), 'createdIds': [c['WorkspaceId'] for c in created if c.get('WorkspaceId')]}
